nner-rail/MANIFEST.json','tests/helpers/pinball-presentation-provenance.mjs','docs/pinball-presentation/BASELINE.json','docs/pinball-presentation/MANIFEST.json','tests/helpers/pinball-palette-provenance.mjs','docs/pinball-palette/BASELINE.json','docs/pinball-palette/MANIFEST.json','tests/helpers/punchline-portal-provenance.mjs','docs/punchline-portal/BASELINE.json','docs/punchline-portal/MANIFEST.json','tests/helpers/pinball-beautify-art-provenance.mjs','docs/pinball-beautify-art/BASELINE.json','docs/pinball-beautify-art/MANIFEST.json','docs/pinball-beautify-art/preimages/portal-taiwanpunchline.png','tests/helpers/pinball-keyboard-copy-provenance.mjs','docs/pinball-keyboard-copy/BASELINE.json','docs/pinball-keyboard-copy/MANIFEST.json','tests/helpers/pinball-entry-provenance.mjs','docs/pinball-entry/BASELINE.json','docs/pinball-entry/MANIFEST.json','tests/helpers/pinball-hud-rotation-provenance.mjs','docs/pinball-hud-rotation/BASELINE.json','docs/pinball-hud-rotation/MANIFEST.json','tests/helpers/provenance-session.mjs'])await writeFile(join(dir,p),read(p));const isolated=await import(pathToFileURL(join(dir,'tests/helpers/shadow-release-provenance.mjs')));isolated.validate(isolated.manifest());const m=structuredClone(isolated.manifest());m.files[0].beforeText+='x';await writeFile(join(dir,'docs/shadow-release/MANIFEST.json'),JSON.stringify(m));assert.throws(()=>isolated.validate(isolated.manifest()));await writeFile(join(dir,'docs/shadow-release/MANIFEST.json'),'{');assert.throws(()=>isolated.manifest(),SyntaxError);assert.throws(()=>isolated.manifest(),SyntaxError);}finally{await rm(dir,{recursive:true,force:true});}});
